import React, { useState } from 'react';
import {
    Typography,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Paper,
    Grid,
    Button,
    Link,
    styled
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import ContactSupportIcon from '@mui/icons-material/ContactSupport';
import { motion } from 'framer-motion';
import { useTranslation } from 'react-i18next';

const StyledAccordion = styled(Accordion)(({ theme }) => ({
    background: 'rgba(255, 255, 255, 0.9)',
    backdropFilter: 'blur(10px)',
    border: '1px solid rgba(255, 255, 255, 0.18)',
    borderRadius: theme.shape.borderRadius * 2,
    boxShadow: '0 4px 12px rgba(0, 0, 0, 0.05)',
    marginBottom: theme.spacing(2),
    '&:before': {
        display: 'none', // Removes the default top border
    },
    '&.Mui-expanded': {
        margin: `${theme.spacing(2)}px 0`, // Keep consistent margin when expanded
    },
}));

const StyledAccordionSummary = styled(AccordionSummary)(({ theme }) => ({
    borderRadius: theme.shape.borderRadius * 2,
    '& .MuiAccordionSummary-content': {
        marginInlineStart: theme.spacing(1),
    },
    '&:hover': {
        background: 'rgba(0, 0, 0, 0.03)',
    }
}));

const FAQSupportSection = () => {
    const { t } = useTranslation('faq');
    const items = t('items', { returnObjects: true });
    const faqData = Array.isArray(items) ? items : [];
    const [expanded, setExpanded] = useState(false);

    const handleChange = (panel) => (event, isExpanded) => {
        setExpanded(isExpanded ? panel : false);
    };

    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: {
                staggerChildren: 0.1,
                delayChildren: 0.2,
            },
        },
    };

    const itemVariants = {
        hidden: { y: 20, opacity: 0 },
        visible: {
            y: 0,
            opacity: 1,
            transition: {
                type: 'spring',
                stiffness: 100,
            },
        },
    };

    return (
        <Paper
            elevation={6}
            sx={{
                mt: 8,
                mb: 6,
                px: { xs: 2, md: 6 },
                py: { xs: 4, md: 6 },
                borderRadius: 5,
                background: 'linear-gradient(145deg, #e8f5e9 0%, #a5d6a7 100%)', // Light Green to Medium Green gradient
                boxShadow: '0 10px 30px rgba(0, 100, 50, 0.1)', // Adjusted shadow color slightly
                overflow: 'hidden',
            }}
        >
            <motion.div variants={containerVariants} initial="hidden" whileInView="visible" viewport={{ once: true, amount: 0.2 }}>
                <Typography
                    variant="h4"
                    component="h2"
                    gutterBottom
                    textAlign="center"
                    sx={{ fontWeight: 600, color: 'primary.dark', mb: 4 }}
                >
                    <motion.span variants={itemVariants}>
                        {t('heading')}
                    </motion.span>
                </Typography>

                <Grid container spacing={4} alignItems="flex-start">
                    <Grid item xs={12} md={8}>
                        <motion.div variants={containerVariants}>
                            {faqData.map((faq, index) => (
                                <motion.div key={index} variants={itemVariants}>
                                    <StyledAccordion
                                        expanded={expanded === `panel${index}`}
                                        onChange={handleChange(`panel${index}`)}
                                    >
                                        <StyledAccordionSummary
                                            expandIcon={<ExpandMoreIcon color="primary" />}
                                            aria-controls={`panel${index}bh-content`}
                                            id={`panel${index}bh-header`}
                                        >
                                            <HelpOutlineIcon sx={{ marginInlineEnd: 1.5, color: 'secondary.main' }} />
                                            <Typography sx={{ fontWeight: 500, color: 'text.primary' }}>{faq.q}</Typography>
                                        </StyledAccordionSummary>
                                        <AccordionDetails>
                                            <Typography sx={{ color: 'text.secondary' }}>{faq.a}</Typography>
                                        </AccordionDetails>
                                    </StyledAccordion>
                                </motion.div>
                            ))}
                        </motion.div>
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <motion.div variants={itemVariants}>
                            <Paper
                                elevation={2}
                                sx={{
                                    p: 3,
                                    textAlign: 'center',
                                    borderRadius: 3,
                                    background: '#ffffff',
                                    height: '100%',
                                    display: 'flex',
                                    flexDirection: 'column',
                                    justifyContent: 'center',
                                }}
                            >
                                <ContactSupportIcon sx={{ fontSize: 48, color: 'primary.main', mb: 2, mx: 'auto' }} />
                                <Typography variant="h6" gutterBottom sx={{ fontWeight: 500 }}>
                                    {t('contact.title')}
                                </Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                                    {t('contact.text')}
                                </Typography>
                                <Button
                                    variant="contained"
                                    color="primary"
                                    component={Link}
                                    href="mailto:support@imuslimlife.com"
                                    sx={{ textTransform: 'none', fontWeight: 600 }}
                                >
                                    {t('contact.button')}
                                </Button>
                            </Paper>
                        </motion.div>
                    </Grid>
                </Grid>
            </motion.div>
        </Paper>
    );
};

export default FAQSupportSection;
